    private string GetCurrentSortValue()
    {
        if (RBsort != null && !string.IsNullOrEmpty(RBsort.SelectedValue))
        {
            return RBsort.SelectedValue;
        }
        return "1";
    }

    protected bool IsSeatViewMode()
    {
        return GetCurrentSortValue() == "3";
